styleBlocks.css:
.import-btn:not([data-chat-empty-view] *) {
  padding: 8px 18px; border-radius: var(--radius-sm); border: 1px solid var(--border);
  font-size: 14px; font-weight: 600; cursor: pointer; font-family: inherit; transition: all 0.15s;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
}

.import-btn:disabled:not([data-chat-empty-view] *) {
  opacity: .5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.modal {
  position: relative; cursor: default;
  background: var(--bg-secondary); border-radius: var(--radius);
  border: 1px solid var(--border); width: 90%; max-width: 700px;
  max-height: 85vh; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; padding: 32px;
  transform: scale(0.96) translateY(8px); opacity: 0;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.gb-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 26px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}

.gb-modal-kicker {
  font-family: var(--font-mono);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.gb-modal-title {
  margin-top: 3px;
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0;
}

.gb-modal-head .modal-close {
  position: static;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
  line-height: 1;
  padding: 0;
  flex-shrink: 0;
}

.gb-modal-head .modal-close:hover {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-hover);
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type,
.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > .modal-header:first-child {
  margin: -32px -32px 20px;
  padding: 22px 56px 18px 26px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0;
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) .modal-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.modal-close {
  position: absolute; top: 16px; right: 16px;
  background: none; border: none; color: var(--text-muted);
  font-size: 24px; cursor: pointer; padding: 0 4px;
}

.modal .modal-unit {
  color: var(--text-muted); font-size: 14px; margin-bottom: 8px;
  /* Source-name + delta + trend separated by middle-dots; let them wrap
     gracefully on narrow viewports rather than overflow the modal box. */
  display: flex; flex-wrap: wrap; gap: 4px 6px; align-items: center;
}

.import-preview-modal:where(.cycle-import-preview-modal) {
  width: min(94vw, 920px);
  max-width: 920px;
  max-height: 90vh;
  padding: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}

:where(.cycle-import-preview-modal) .import-review-summary {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(150px, .7fr);
  gap: 10px 14px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 70%, transparent);
}

:where(.cycle-import-preview-modal) .import-review-file {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

:where(.cycle-import-preview-modal) .import-review-label {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

:where(.cycle-import-preview-modal) .import-review-file strong {
  min-width: 0;
  color: var(--text-primary);
  font-size: 13px;
  overflow-wrap: anywhere;
}

:where(.cycle-import-preview-modal) .import-review-stats {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

:where(.cycle-import-preview-modal) .import-review-stat {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 24px;
  padding: 3px 9px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
}

:where(.cycle-import-preview-modal) .import-review-warning {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--yellow);
  border-radius: var(--radius-sm);
  background: var(--yellow-bg);
  color: var(--yellow);
  font-size: 13px;
  line-height: 1.5;
}

:where(.cycle-import-preview-modal) .import-table-wrap {
  margin-top: 16px;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 62%, transparent);
  -webkit-overflow-scrolling: touch;
}

.cycle-import-conflicts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}

.cycle-import-table-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-top: 16px;
}

.cycle-import-table-heading span {
  color: var(--text-muted);
  font-size: 12px;
  text-align: right;
}

.cycle-import-row-status {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 2px 7px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  line-height: 1.2;
  white-space: nowrap;
}

.cycle-import-row-status-ready {
  border-color: color-mix(in srgb, var(--green) 28%, var(--border));
  background: color-mix(in srgb, var(--green) 9%, transparent);
  color: var(--green);
}

.cycle-import-row-status-conflict {
  border-color: color-mix(in srgb, var(--yellow) 36%, var(--border));
  background: color-mix(in srgb, var(--yellow) 10%, transparent);
  color: var(--yellow);
}

.cycle-import-table tr[data-import-status="unmatched"] {
  background: color-mix(in srgb, var(--yellow) 5%, transparent);
}

.cycle-import-privacy-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 54%, transparent);
  color: var(--text-secondary);
}

.cycle-import-privacy-note > span:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.cycle-import-conflict-option {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 68%, transparent);
  color: var(--text-secondary);
  cursor: pointer;
  line-height: 1.4;
}

.cycle-import-conflict-option:has(input:checked) {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  background: color-mix(in srgb, var(--accent) 12%, var(--bg-card));
}

.cycle-import-conflict-option input {
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  margin: 1px 0 0;
  accent-color: var(--accent);
}

.cycle-import-conflict-option span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

:where(.cycle-import-preview-modal) .import-review-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 96%, var(--bg-card));
}

:where(.cycle-import-preview-modal) .import-table th {
  background: var(--bg-card); padding: 8px 12px; text-align: left;
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted);
}

.import-preview-modal:where(.cycle-import-preview-modal),
#import-modal.import-preview-modal:where(.cycle-import-preview-modal),
.modal.import-preview-modal:where(.cycle-import-preview-modal) {
    width: calc(100vw - 12px);
    height: calc(100vh - 12px);
    height: calc(100dvh - 12px);
    max-height: none;
    padding: 0;
  }

:where(.cycle-import-preview-modal) .import-table,
:where(.cycle-import-preview-modal) .import-table tbody,
:where(.cycle-import-preview-modal) .import-table tr,
:where(.cycle-import-preview-modal) .import-table td {
    display: block;
    width: 100%;
    box-sizing: border-box;
  }

:where(.cycle-import-preview-modal) .import-table tr {
    position: relative;
    margin-bottom: 9px;
    padding: 13px 11px 11px;
    border: 1px solid var(--border);
    border-left-width: 4px;
    border-radius: var(--radius-sm);
    background: color-mix(in srgb, var(--bg-card) 72%, transparent);
  }

:where(.cycle-import-preview-modal) .import-table td {
    display: grid;
    grid-template-columns: minmax(74px, 28%) minmax(0, 1fr);
    align-items: start;
    gap: 8px;
    padding: 5px 0;
    border-bottom: 0;
    white-space: normal;
  }

:where(.cycle-import-preview-modal) .import-table td::before {
    content: attr(data-label);
    color: var(--text-muted);
    font-family: var(--font-mono);
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    line-height: 1.35;
  }

:where(.cycle-import-preview-modal) .import-review-actions {
    position: sticky;
    bottom: 0;
    z-index: 3;
    padding: 12px;
    flex-wrap: wrap;
    box-shadow: 0 -8px 18px color-mix(in srgb, var(--bg-primary) 14%, transparent);
  }

.cycle-icon-btn,
.cycle-action-btn {
  min-width: 36px;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.05s;
}

.cycle-icon-btn:hover,
.cycle-action-btn:hover {
  background: var(--bg-hover);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--text-primary);
}

.cycle-editor-section {
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 70%, transparent);
}

.cycle-import-coverage {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 12px;
}

.cycle-import-coverage span,
.cycle-mini-action {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.25;
}

.cycle-source-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 36px;
  align-items: start;
  gap: 10px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.cycle-source-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cycle-import-batches {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 3px;
}

.cycle-mini-action {
  min-width: 0;
  padding: 3px 8px;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}

.cycle-mini-action:hover {
  border-color: color-mix(in srgb, var(--red) 50%, var(--border));
  color: var(--red);
}

.cycle-delete-btn:hover {
  border-color: color-mix(in srgb, var(--red) 55%, var(--border));
  color: var(--red);
}
